<script setup lang="ts">

import {ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api} from './session'
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('ShippingPackingEditor')
const props=defineProps<{plan:any}>(),emit=defineEmits(['close','saved'])
const busy=ref(false),error=ref('')
const boxes=ref(props.plan.packing.boxes.map((b:any)=>({...b,items:props.plan.items.map((i:any)=>({sku:i.sku,fnsku:i.fnsku,name:i.name,quantity:b.items.find((x:any)=>x.sku===i.sku)?.quantity||0}))})))
const metrics=[{key:'weight_kg',label:'重量 kg'},{key:'length_cm',label:'长 cm'},{key:'width_cm',label:'宽 cm'},{key:'height_cm',label:'高 cm'}]
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await api(`/shipping/${props.plan.id}/packing-edit`,{revision:props.plan.revision,boxes:boxes.value.map((b:any)=>({weight_kg:b.weight_kg,length_cm:b.length_cm,width_cm:b.width_cm,height_cm:b.height_cm,items:b.items.map((i:any)=>({sku:i.sku,quantity:i.quantity}))}))});ElMessage.success('装箱单已保存');emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(){if(busy.value)return;try{await ElMessageBox.confirm('删除当前装箱单和装箱数量？删除后需要重新上传，历史文件和日志保留。','删除装箱单',{type:'warning'});busy.value=true;await api(`/shipping/${props.plan.id}/packing-delete`,{revision:props.plan.revision});ElMessage.success('装箱单已删除，请重新上传');emit('saved')}catch(e){if(e instanceof Error)error.value=e.message}finally{busy.value=false}}
</script>
<template><el-dialog :model-value="true" title="编辑装箱单" width="min(1100px,96vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" @close="emit('close')"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form :disabled="busy"><section v-for="(box,index) in boxes" :key="index" class="packing-edit-box"><h4>第 {{box.number}} 箱</h4><div class="packing-metrics"><el-form-item v-for="m in metrics" :key="m.key" :label="m.label"><el-input-number v-model="box[m.key]" :min="0.001" :max="100000" :precision="3" :aria-label="`第${box.number}箱${m.label}`"/></el-form-item></div><template v-if="true"><TableReset :table-key="'ShippingPackingEditor/'+'items'"/><el-table :data-width-key="'ShippingPackingEditor/'+'items'"    :data="box.items" @header-dragend="(w:number,_old:number,c:any)=>widths.resize('items',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>widths.resetColumn('items',c,e)"><el-table-column  :width="widths.width('items','sku',350)" column-key="sku" prop="sku" label="SKU / FNSKU" ><template #default="{row}">{{row.sku}}<small>{{row.fnsku}}</small></template></el-table-column><el-table-column  :width="widths.width('items','name',350)" column-key="name" prop="name" label="品名" /><el-table-column  :width="widths.width('items','quantity',200)" column-key="quantity" label="装箱数量" ><template #default="{row}"><el-input-number v-model="row.quantity" :min="0" :max="100000" :precision="0" :aria-label="`${row.sku}第${box.number}箱数量`"/></template></el-table-column></el-table></template></section></el-form><template #footer><el-button :disabled="busy" @click="emit('close')">取消</el-button><el-button type="danger" plain :disabled="busy" @click="remove">删除装箱单</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></template>
<style scoped>.packing-edit-box{margin-bottom:22px}.packing-metrics{display:flex;gap:16px;flex-wrap:wrap}.packing-metrics .el-form-item{margin-bottom:12px}small{display:block;color:#8a9b92;font-size:12px;margin-top:4px}</style>
